        }
        requireExpectedVersion(evidence, request.expectedVersion());
        LocalDateTime now = clock.nowUtc();
        LocalDateTime validFrom = request.validFrom() != null ? request.validFrom() : now;
        LocalDateTime validTo = request.validTo();
        if (!validTo.isAfter(validFrom)) throw badRequest("有效期终点须晚于起点");
        if (validTo.isAfter(validFrom.plusMinutes(MAX_VALIDITY_MINUTES))) throw badRequest("有效期最长一小时");
        if (!validTo.isAfter(now)) throw badRequest("有效期终点须晚于当前时刻");
        String copyId = "CPY-" + UUID.randomUUID().toString().replace("-", "").substring(0, 24);
        String watermark = "COPY[" + copyId + "]|REVIEWER[" + request.reviewerId() + "]";
        copyRepository.insert(copyId, evidenceKey, request.reviewerId(), evidence.digest(), watermark,
                evidence.syntheticText(), validFrom, validTo, now, LocalDateTime.now());
        InspectionCopy copy = copyRepository.findByCopyId(copyId).orElseThrow();
        String metadataJson = toJson(toView(copy));
        commandLogRepository.insert(request.requestId(), actorId, OP_COPY_ISSUE, requestHash, 201, metadataJson, LocalDateTime.now());
        return new StoredResponse(201, toJson(toContentView(copy)));
